const query=document.querySelector("#find-tool"),categories=document.querySelector(".kit-jumps"),status=document.querySelector("#tool-search-status");function filterTools(){const r=query.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let e=0;for(const t of document.querySelectorAll(".kit-group")){let o=0;for(const n of t.querySelectorAll(".kit-card")){const s=n.textContent.toLowerCase();n.hidden=!r.every(c=>s.includes(c)),n.hidden||o++}t.hidden=o===0,categories.querySelector('a[href="#'+t.id+'"]').hidden=t.hidden,e+=o}categories.hidden=e===0,r.length?e?status.textContent=e===1?"1 tool matches your search.":e+" tools match your search.":status.textContent="No tools match. Try a service, task or industry.":status.textContent=""}query.addEventListener("input",filterTools),window.addEventListener("pageshow",filterTools);
